/** One task as a line of text, for example "[x] 3 Buy milk (high)". */
export function formatTask(task) {
  const box = task.done ? "[x]" : "[ ]";
  const priority = (task.priority === "high" || task.priority === "low") 
    ? ` (${task.priority})` 
    : "";
  return `${box} ${task.id} ${task.title}${priority}`;
}

/** Every task on its own line, or a short message when there are none. */
export function formatList(tasks) {
  if (tasks.length === 0) return "No tasks.";
  return tasks.map(formatTask).join("\n");
}

/** An in-memory list of tasks. Ids start at 1 and are never reused. */
export function createStore() {
  const tasks = [];
  let nextId = 1;

  function find(id) {
    const task = tasks.find((t) => t.id === id);
    if (!task) throw new Error(`No task with id ${id}`);
    return task;
  }

  return {
    add(title, priority = "normal") {
      const trimmed = String(title ?? "").trim();
      if (trimmed === "") throw new Error("A task needs a title");
      const task = { id: nextId++, title: trimmed, priority, done: false };
      tasks.push(task);
      return { ...task };
    },

    complete(id) {
      const task = find(id);
      task.done = true;
      return { ...task };
    },

    remove(id) {
      const task = find(id);
      tasks.splice(tasks.indexOf(task), 1);
    },

    /** 
     * Copies of every task, sorted by priority (high, then normal, then low),
     * maintaining chronological order within each level.
     */
    all() {
      const weights = { high: 0, normal: 1, low: 2 };
      return [...tasks]
        .sort((a, b) => weights[a.priority] - weights[b.priority])
        .map((t) => ({ ...t }));
    },
  };
}

