  const tasks = [];
  let nextId = 1;

  function find(id) {
    const task = tasks.find((t) => t.id === id);
    if (!task) throw new Error(`No task with id ${id}`);
    return task;
  }

  return {
    add(title, priority = "normal") {
      const trimmed = String(title ?? "").trim();
      if (trimmed === "") throw new Error("A task needs a title");
      const task = { id: nextId++, title: trimmed, priority, done: false };
      tasks.push(task);
      return { ...task };
    },

    complete(id) {
      const task = find(id);
      task.done = true;
      return { ...task };
    },

    remove(id) {
      const task = find(id);
      tasks.splice(tasks.indexOf(task), 1);
    },

    /** 
     * Copies of every task, sorted by priority (high, then normal, then low),
     * maintaining chronological order within each level.
     */
    all() {
      const weights = { high: 0, normal: 1, low: 2 };
      // Map to include index to guarantee stable sort across environments
      return tasks
        .map((task, index) => ({ task, index }))
        .sort((a, b) => {
          const weightDiff = weights[a.task.priority] - weights[b.task.priority];
          if (weightDiff !== 0) return weightDiff;
          return a.index - b.index;
        })
        .map(({ task }) => ({ ...task }));
    },
  };
}

import { formatList } from "./format.js";

/**
 * Run one command against a store and return the text to print.
 *
 *   add <title...>   add a task
 *   done <id>        mark a task as done
 *   remove <id>      delete a task
 *   list             show every task
 */
export function run(args, store) {
  const [command, ...rest] = args;
  switch (command) {
    case "add": {
      let priority;
      const titleArgs = [];

      for (let i = 0; i < rest.length; i++) {
        if (rest[i] === "--priority") {
          priority = rest[++i];
          if (!["low", "normal", "high"].includes(priority)) {
            throw new Error(`Invalid priority: ${priority}`);
          }
        } else {
          titleArgs.push(rest[i]);
        }
      }

      const task = store.add(titleArgs.join(" "), priority);
      return `Added ${task.id}: ${task.title}`;
    }
    case "done": {
      const task = store.complete(parseId(rest[0]));
      return `Completed ${task.id}`;
    }
    case "remove": {
      const id = parseId(rest[0]);
      store.remove(id);
      return `Removed ${id}`;
    }
    case "list":
      return formatList(store.all());
    default:
      throw new Error(`Unknown command: ${command ?? "(none)"}`);
  }
}

function parseId(text) {
  const id = Number(text);
  if (!Number.isInteger(id) || id < 1) throw new Error(`Not a task id: ${text}`);
  return id;
}

