import assert from "node:assert/strict";
import { test } from "node:test";
import { run } from "../src/cli.js";
import { createStore } from "../src/store.js";
import { formatTask } from "../src/format.js";

test("AC-1: add command with priority flag creates task with specified priority", () => {
  const store = createStore();
  run(["add", "High Task", "--priority", "high"], store);
  run(["add", "Normal Task", "--priority", "normal"], store);
  run(["add", "Low Task", "--priority", "low"], store);

  const tasks = store.all();
  // Sorting is expected, so we find by title
  assert.equal(tasks.find(t => t.title === "High Task").priority, "high");
  assert.equal(tasks.find(t => t.title === "Normal Task").priority, "normal");
  assert.equal(tasks.find(t => t.title === "Low Task").priority, "low");
});

test("AC-2: add command without priority flag defaults to normal", () => {
  const store = createStore();
  run(["add", "Default Task"], store);
  const tasks = store.all();
  assert.equal(tasks[0].priority, "normal");
});

test("AC-3: add command with invalid priority level throws error and does not add task", () => {
  const store = createStore();
  assert.throws(() => run(["add", "Urgent Task", "--priority", "urgent"], store), Error);
  assert.equal(store.all().length, 0);
});

test("AC-4 & AC-5: list displays tasks sorted by priority then chronologically", () => {
  const store = createStore();
  run(["add", "Normal 1", "--priority", "normal"], store);
  run(["add", "High 1", "--priority", "high"], store);
  run(["add", "Low 1", "--priority", "low"], store);
  run(["add", "High 2", "--priority", "high"], store);
  run(["add", "Normal 2", "--priority", "normal"], store);
  run(["add", "Low 2", "--priority", "low"], store);

  const tasks = store.all();
  const titles = tasks.map(t => t.title);
  assert.deepEqual(titles, ["High 1", "High 2", "Normal 1", "Normal 2", "Low 1", "Low 2"]);
});

test("AC-6: high and low priorities display priority label in brackets", () => {
  const highTask = { id: 1, title: "High Task", priority: "high", done: false };
  const lowTask = { id: 2, title: "Low Task", priority: "low", done: false };

  assert.ok(formatTask(highTask).includes("(high)"), "Should contain (high)");
  assert.ok(formatTask(lowTask).includes("(low)"), "Should contain (low)");
});

test("AC-7: normal priority does not display priority label", () => {
  const normalTask = { id: 1, title: "Normal Task", priority: "normal", done: false };
  const result = formatTask(normalTask);
  assert.ok(!result.includes("(normal)"), "Should not contain (normal)");
  assert.ok(!result.includes("(high)") && !result.includes("(low)"), "Should not contain other labels");
});
